From 1070a26d05b9573d712ebb8767c22e34883db667 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:48:30 +0100
Subject: [PATCH] libtaskmanager: add a filterTransients property to TasksModel

Transient windows such as dialogs were always treated as skip-taskbar,
so applets using TasksModel could never see them. Add an IsTransient
role and a filterTransients property that applets can turn off.

BUG: 405657
---
 libtaskmanager/abstracttasksmodel.cpp   |  1 +
 libtaskmanager/abstracttasksmodel.h     |  1 +
 libtaskmanager/taskfilterproxymodel.cpp | 20 +++++++++++++++++++-
 libtaskmanager/taskfilterproxymodel.h   | 23 +++++++++++++++++++++++
 libtaskmanager/tasksmodel.cpp           | 11 +++++++++++
 libtaskmanager/tasksmodel.h             | 21 +++++++++++++++++++++
 libtaskmanager/waylandtasksmodel.cpp    |  6 ++++--
 7 files changed, 80 insertions(+), 3 deletions(-)

diff --git a/libtaskmanager/abstracttasksmodel.cpp b/libtaskmanager/abstracttasksmodel.cpp
index 4285e99393..c080bb16ca 100644
--- a/libtaskmanager/abstracttasksmodel.cpp
+++ b/libtaskmanager/abstracttasksmodel.cpp
@@ -85,6 +85,7 @@ QVariant AbstractTasksModel::data(const QModelIndex &, int role) const
         return QStringList();
     case IsDemandingAttention:
     case SkipTaskbar:
+    case IsTransient:
     case SkipPager:
         return false;
     case AppPid:
diff --git a/libtaskmanager/abstracttasksmodel.h b/libtaskmanager/abstracttasksmodel.h
index cb6c38f998..1e6583384c 100644
--- a/libtaskmanager/abstracttasksmodel.h
+++ b/libtaskmanager/abstracttasksmodel.h
@@ -96,6 +96,7 @@ public:
         IsExcludedFromCapture, /**< Whether the task's window has been hidden from screencasts. @since 6.6 */
         StorageId, /** The KService storageId for the underlying service. @since 6.8  */
         IsMapped, /**< Whether the window is mapped, @since 6.8 */
+        IsTransient, /**< Whether the window is a transient (e.g. a dialog) of another window. @since 6.9 */
     };
     Q_ENUM(AdditionalRoles)

diff --git a/libtaskmanager/taskfilterproxymodel.cpp b/libtaskmanager/taskfilterproxymodel.cpp
index 4139ad787d..9cb94c2318 100644
--- a/libtaskmanager/taskfilterproxymodel.cpp
+++ b/libtaskmanager/taskfilterproxymodel.cpp
@@ -40,6 +40,7 @@ public:
     bool filterNotMaximized = false;
     bool filterHidden = false;
     bool filterSkipTaskbar = true;
+    bool filterTransients = true;
     bool filterSkipPager = false;

     bool demandingAttentionSkipsFilters = true;
@@ -338,6 +339,22 @@ void TaskFilterProxyModel::setFilterSkipTaskbar(bool filter)
     }
 }

+bool TaskFilterProxyModel::filterTransients() const
+{
+    return d->filterTransients;
+}
+
+void TaskFilterProxyModel::setFilterTransients(bool filter)
+{
+    if (d->filterTransients != filter) {
+        d->filterTransients = filter;
+
+        invalidateFilter();
+
+        Q_EMIT filterTransientsChanged();
+    }
+}
+
 bool TaskFilterProxyModel::filterSkipPager() const
 {
     return d->filterSkipPager;
@@ -401,7 +418,8 @@ bool TaskFilterProxyModel::acceptsRow(int sourceRow) const
     }

     // Filter tasks that are not to be shown on the task bar.
-    if (d->filterSkipTaskbar && sourceIdx.data(AbstractTasksModel::SkipTaskbar).toBool()) {
+    if (d->filterSkipTaskbar && sourceIdx.data(AbstractTasksModel::SkipTaskbar).toBool()
+        && (d->filterTransients || !sourceIdx.data(AbstractTasksModel::IsTransient).toBool())) {
         return false;
     }

diff --git a/libtaskmanager/taskfilterproxymodel.h b/libtaskmanager/taskfilterproxymodel.h
index e37c071159..d2633f4e18 100644
--- a/libtaskmanager/taskfilterproxymodel.h
+++ b/libtaskmanager/taskfilterproxymodel.h
@@ -48,6 +48,7 @@ class TASKMANAGER_EXPORT TaskFilterProxyModel : public QSortFilterProxyModel, pu
     Q_PROPERTY(bool filterNotMaximized READ filterNotMaximized WRITE setFilterNotMaximized NOTIFY filterNotMaximizedChanged)
     Q_PROPERTY(bool filterHidden READ filterHidden WRITE setFilterHidden NOTIFY filterHiddenChanged)
     Q_PROPERTY(bool filterSkipTaskbar READ filterSkipTaskbar WRITE setFilterSkipTaskbar NOTIFY filterSkipTaskbarChanged)
+    Q_PROPERTY(bool filterTransients READ filterTransients WRITE setFilterTransients NOTIFY filterTransientsChanged)
     Q_PROPERTY(bool filterSkipPager READ filterSkipPager WRITE setFilterSkipPager NOTIFY filterSkipPagerChanged)

     Q_PROPERTY(bool demandingAttentionSkipsFilters READ demandingAttentionSkipsFilters WRITE setDemandingAttentionSkipsFilters NOTIFY
@@ -350,6 +351,27 @@ public:
      **/
     void setFilterSkipTaskbar(bool filter);

+    /**
+     * Whether transient windows (e.g. dialogs) should be filtered along with
+     * other tasks which should be omitted from 'task bars'. Only has an effect
+     * when filterSkipTaskbar is @c true. Defaults to @c true.
+     *
+     * @see setFilterTransients
+     * @returns @c true if transient windows should be filtered.
+     * @since 6.9
+     **/
+    bool filterTransients() const;
+
+    /**
+     * Set whether transient windows (e.g. dialogs) should be filtered along
+     * with other tasks which should be omitted from 'task bars'.
+     *
+     * @see filterTransients
+     * @param filter Whether transient windows should be filtered.
+     * @since 6.9
+     **/
+    void setFilterTransients(bool filter);
+
     /**
      * Whether tasks which should be omitted from 'pagers' should be
      * filtered. Defaults to @c true.
@@ -422,6 +444,7 @@ Q_SIGNALS:
     void filterNotMaximizedChanged() const;
     void filterHiddenChanged() const;
     void filterSkipTaskbarChanged() const;
+    void filterTransientsChanged() const;
     void filterSkipPagerChanged() const;
     void demandingAttentionSkipsFiltersChanged() const;
     void hideActivatedLaunchersChanged() const;
diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..d31ef49555 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -270,6 +270,7 @@ void TasksModel::Private::initModels()
     QObject::connect(filterProxyModel, &TaskFilterProxyModel::filterNotMinimizedChanged, q, &TasksModel::filterNotMinimizedChanged);
     QObject::connect(filterProxyModel, &TaskFilterProxyModel::filterNotMaximizedChanged, q, &TasksModel::filterNotMaximizedChanged);
     QObject::connect(filterProxyModel, &TaskFilterProxyModel::filterHiddenChanged, q, &TasksModel::filterHiddenChanged);
+    QObject::connect(filterProxyModel, &TaskFilterProxyModel::filterTransientsChanged, q, &TasksModel::filterTransientsChanged);
     QObject::connect(filterProxyModel, &TaskFilterProxyModel::hideActivatedLaunchersChanged, q, &TasksModel::hideActivatedLaunchersChanged);

     groupingProxyModel = new TaskGroupingProxyModel(q);
@@ -1188,6 +1189,16 @@ void TasksModel::setFilterHidden(bool filter)
     d->filterProxyModel->setFilterHidden(filter);
 }

+bool TasksModel::filterTransients() const
+{
+    return d->filterProxyModel->filterTransients();
+}
+
+void TasksModel::setFilterTransients(bool filter)
+{
+    d->filterProxyModel->setFilterTransients(filter);
+}
+
 TasksModel::SortMode TasksModel::sortMode() const
 {
     return d->sortMode;
diff --git a/libtaskmanager/tasksmodel.h b/libtaskmanager/tasksmodel.h
index 9cdad29325..27dc8d1368 100644
--- a/libtaskmanager/tasksmodel.h
+++ b/libtaskmanager/tasksmodel.h
@@ -73,6 +73,7 @@ class TASKMANAGER_EXPORT TasksModel : public QSortFilterProxyModel, public Abstr
     Q_PROPERTY(bool filterNotMinimized READ filterNotMinimized WRITE setFilterNotMinimized NOTIFY filterNotMinimizedChanged)
     Q_PROPERTY(bool filterNotMaximized READ filterNotMaximized WRITE setFilterNotMaximized NOTIFY filterNotMaximizedChanged)
     Q_PROPERTY(bool filterHidden READ filterHidden WRITE setFilterHidden NOTIFY filterHiddenChanged)
+    Q_PROPERTY(bool filterTransients READ filterTransients WRITE setFilterTransients NOTIFY filterTransientsChanged)

     Q_PROPERTY(SortMode sortMode READ sortMode WRITE setSortMode NOTIFY sortModeChanged)
     Q_PROPERTY(bool separateLaunchers READ separateLaunchers WRITE setSeparateLaunchers NOTIFY separateLaunchersChanged)
@@ -421,6 +422,25 @@ public:
      **/
     void setFilterHidden(bool filter);

+    /**
+     * Whether transient windows (e.g. dialogs) should be filtered. Defaults
+     * to @c true.
+     *
+     * @see setFilterTransients
+     * @returns @c true if transient windows should be filtered.
+     * @since 6.9
+     **/
+    bool filterTransients() const;
+
+    /**
+     * Set whether transient windows (e.g. dialogs) should be filtered.
+     *
+     * @see filterTransients
+     * @param filter Whether transient windows should be filtered.
+     * @since 6.9
+     **/
+    void setFilterTransients(bool filter);
+
     /**
      * The sort mode used in sorting tasks. Defaults to SortAlpha.
      *
@@ -1035,6 +1055,7 @@ Q_SIGNALS:
     void filterNotMinimizedChanged() const;
     void filterNotMaximizedChanged() const;
     void filterHiddenChanged() const;
+    void filterTransientsChanged() const;
     void sortModeChanged() const;
     void separateLaunchersChanged() const;
     void launchInPlaceChanged() const;
diff --git a/libtaskmanager/waylandtasksmodel.cpp b/libtaskmanager/waylandtasksmodel.cpp
index ed0b90cbbf..49ec02e830 100644
--- a/libtaskmanager/waylandtasksmodel.cpp
+++ b/libtaskmanager/waylandtasksmodel.cpp
@@ -669,11 +669,11 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
             if (leader) { // leader change.
                 transients.insert(window, leader);
             } else { // lost a leader, add to regular windows list.
-                dataChanged(window, SkipTaskbar);
+                dataChanged(window, QList<int>{SkipTaskbar, IsTransient});
             }
         } else if (leader) { // gained a leader, remove from regular windows list.
             transients.insert(window, leader);
-            dataChanged(window, SkipTaskbar);
+            dataChanged(window, QList<int>{SkipTaskbar, IsTransient});
         }
     });

@@ -968,6 +968,8 @@ QVariant WaylandTasksModel::data(const QModelIndex &index, int role) const
         return window->windowState.testFlag(PlasmaWindow::state::state_demands_attention) || d->transientsDemandingAttention.contains(window);
     case SkipTaskbar:
         return window->windowState.testFlag(PlasmaWindow::state::state_skiptaskbar) || d->transients.contains(window);
+    case IsTransient:
+        return d->transients.contains(window);
     case SkipPager:
         return false;
     case AppPid:
